package paasio

import (
	"io"
	"sync"
)

// readCounter is an io.Reader that counts the number of bytes read and the
// number of Read calls made.
type readCounter struct {
	reader io.Reader
	mu     sync.Mutex
	n      int64
	nops   int
}

// writeCounter is an io.Writer that counts the number of bytes written and
// the number of Write calls made.
type writeCounter struct {
	writer io.Writer
	mu     sync.Mutex
	n      int64
	nops   int
}

// readWriteCounter satisfies ReadWriteCounter by combining a readCounter and
// a writeCounter.
type readWriteCounter struct {
	*readCounter
	*writeCounter
}

func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{writer: writer}
}

func NewReadCounter(reader io.Reader) ReadCounter {
